definition.script:
properties([
  pipelineTriggers([]),
  disableConcurrentBuilds(),
  buildDiscarder(logRotator(numToKeepStr: '20')),
  parameters([booleanParam(name: 'VERIFY_ONLY', defaultValue: false,
    description: '체크하면 검증만 실행하고 운영 배포를 생략합니다.')])
])
node {
  timestamps {
    stage('Checkout main') {
      deleteDir()
      withCredentials([usernamePassword(
        credentialsId: 'accountbook-github',
        usernameVariable: 'GITHUB_USERNAME',
        passwordVariable: 'GITHUB_TOKEN'
      )]) {
        sh '''#!/bin/sh
set -eu
askpass="$(mktemp)"
trap 'rm -f "$askpass"' EXIT HUP INT TERM
cat > "$askpass" <<'EOF'
#!/bin/sh
case "$1" in
  *Username*) printf '%s\\n' "$GITHUB_USERNAME" ;;
  *Password*) printf '%s\\n' "$GITHUB_TOKEN" ;;
  *) exit 1 ;;
esac
EOF
chmod 700 "$askpass"
GIT_ASKPASS="$askpass" GIT_TERMINAL_PROMPT=0 git clone --depth 1 --branch main https://github.com/kyoungrae/counsulting-manager.git .
git rev-parse --verify HEAD
'''
      }
    }
    load 'Jenkinsfile'
  }
}
